// 测试程序：验证"分数方程"(海淀真题 b4238)考生程序的正确性
// 多解问题：校验 x, y, z 为互不相等的正整数且 1/x + 1/y + 1/z = 2/n（精确整数判定）。
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <sstream>
#include <fstream>
#include <iostream>
#include <unistd.h>
#include <boost/multiprecision/cpp_int.hpp>
using boost::multiprecision::cpp_int;

static std::string runProgram(const std::string& exePath, const std::string& input) {
    std::string inFile = "/tmp/oa1_b4238_in_" + std::to_string(getpid()) + ".txt";
    std::string outFile = "/tmp/oa1_b4238_out_" + std::to_string(getpid()) + ".txt";
    { std::ofstream fin(inFile); fin << input; }
    std::string cmd = "\"" + exePath + "\" < \"" + inFile + "\" > \"" + outFile + "\" 2>/dev/null";
    int rc = system(cmd.c_str());
    (void)rc;
    std::ifstream fout(outFile);
    std::stringstream ss; ss << fout.rdbuf();
    std::remove(inFile.c_str()); std::remove(outFile.c_str());
    return ss.str();
}

struct Case { std::string input; cpp_int n; };

int main(int argc, char** argv) {
    if (argc < 2) { std::cerr << "用法: " << argv[0] << " <考生二进制程序路径>\n"; return 1; }
    std::string exePath = argv[1];
    std::vector<Case> cases = { {"3\n", 3}, {"7\n", 7} };
    int total = (int)cases.size(), passed = 0;
    std::vector<int> failedIdx;
    std::vector<std::string> detail(total);
    for (int t = 0; t < total; t++) {
        std::string out = runProgram(exePath, cases[t].input);
        std::stringstream ss(out);
        std::vector<cpp_int> v(3);
        bool ok = true;
        for (int i = 0; i < 3; i++) if (!(ss >> v[i])) ok = false;
        if (ok) {
            for (int i = 0; i < 3; i++) if (v[i] <= 0) ok = false;
            for (int i = 0; i < 3 && ok; i++)
                for (int j = i + 1; j < 3; j++) if (v[i] == v[j]) ok = false;
        }
        if (ok) {
            // 1/x + 1/y + 1/z = 2/n  <=>  n*(yz + xz + xy) = 2*x*y*z
            cpp_int lhs = cases[t].n * (v[0]*v[1] + v[0]*v[2] + v[1]*v[2]);
            cpp_int rhs = 2 * v[0] * v[1] * v[2];
            if (lhs != rhs) ok = false;
        }
        if (ok) passed++; else { failedIdx.push_back(t); detail[t] = "输出: " + out; }
    }
    printf("=== 分数方程 测试结果：%d / %d 通过 ===\n", passed, total);
    if (!failedIdx.empty()) {
        printf("\n以下样例不符合预期：\n");
        for (int idx : failedIdx) printf("第 %d 组：%s\n", idx + 1, detail[idx].c_str());
    } else printf("全部样例通过！\n");
    return failedIdx.empty() ? 0 : 1;
}

